// audio.c - the sound bank. Wav files from assets/audio/<name>.wav (generated by
// tools/audio/gen_sfx.py) are preferred; any missing event falls back to the old
// procedural tone so the game never goes silent. Music streams per biome.
#include "platform/audio.h"
#include "core/settings.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// ---- per-event table: file name, fallback synth params, volume, pitch variance ----
typedef struct {
    const char *name;       // assets/audio/<name>.wav
    float freq, secs, decay; int kind;   // fallback tone (0 sine, 1 square, 2 noise)
    float vol;              // event mix level (multiplied by SETTINGS.sfxVol)
    float pitchVar;         // +/- random pitch spread per play
} SfxDef;

static const SfxDef SFX[SFX_COUNT] = {
    [SFX_SHOOT]     = { "shoot",     420, 0.08f, 26, 1, 0.55f, 0.08f },
    [SFX_HIT]       = { "hit",       120, 0.30f, 10, 2, 0.90f, 0.05f },
    [SFX_EXPLODE]   = { "explode",    90, 0.18f, 16, 2, 0.80f, 0.10f },
    [SFX_PICKUP]    = { "pickup",    720, 0.06f, 30, 0, 0.60f, 0.06f },
    [SFX_LEVELUP]   = { "levelup",   520, 0.30f,  8, 0, 0.90f, 0.00f },
    [SFX_BOSS_DIE]  = { "boss_die",   70, 0.80f,  4, 0, 1.00f, 0.00f },
    [SFX_DODGE]     = { "dodge",     240, 0.12f, 18, 2, 0.50f, 0.06f },
    [SFX_UI_MOVE]   = { "ui_move",   880, 0.04f, 40, 1, 0.35f, 0.00f },
    [SFX_UI_SELECT] = { "ui_select", 660, 0.09f, 24, 1, 0.50f, 0.00f },
    [SFX_CHARGE]      = { "charge",      460, 0.10f, 20, 0, 0.45f, 0.00f },
    [SFX_CHARGE_STEP] = { "charge_step", 220, 0.16f, 14, 1, 0.75f, 0.00f },
    [SFX_CHARGE_FULL] = { "charge_full", 130, 0.40f,  7, 0, 0.90f, 0.00f },
    [SFX_SHOOT_BIG]   = { "shoot_big",   110, 0.50f,  7, 2, 1.00f, 0.00f },
};

// audio-only RNG: pitch variance must never consume the sim RNG (determinism)
static unsigned g_arng = 0x9d2c5680u;
static float arand(void) {   // [0,1)
    g_arng = g_arng * 1664525u + 1013904223u;
    return (float)(g_arng >> 8) / 16777216.0f;
}

// Perceptual volume taper: the slider/setting stays a plain linear 0..1 (and the UI still
// shows it as a plain 0..100%), but ears hear loudness roughly logarithmically, so a
// straight linear gain barely drops in perceived volume until ~10%, then falls off a
// cliff. Map the 0..1 setting onto a -40dB..0dB range (a gentle, DAW-typical floor —
// quieter than that reads as "off" anyway) and convert that to linear gain, so every
// slider notch now feels like an even step in loudness. 0 still maps to true silence.
static float volume_curve(float linear01) {
    if (linear01 <= 0.0f) return 0.0f;
    const float minDb = -40.0f;
    float db = minDb * (1.0f - linear01);      // 0 -> -40dB (near-silent), 1 -> 0dB (unity)
    return powf(10.0f, db / 20.0f);
}

// kind: 0 sine, 1 square, 2 noise
static Sound make_tone(float freq, float seconds, float decay, int kind) {
    int sampleRate = 22050; int frames = (int)(sampleRate * seconds);
    short *data = (short *)malloc(sizeof(short) * frames);
    for (int i = 0; i < frames; i++) {
        float t = (float)i / sampleRate, env = expf(-t * decay), ph = 2.0f*PI*freq*t, s;
        if (kind == 0) s = sinf(ph);
        else if (kind == 1) s = (sinf(ph) > 0 ? 1.0f : -1.0f);
        else s = ((float)rand()/(float)RAND_MAX*2.0f - 1.0f);   // white noise (one-time synth; not sim RNG)
        s += 0.3f * sinf(ph*0.5f);
        data[i] = (short)(s * env * 8000.0f);
    }
    Wave w = { .frameCount=frames, .sampleRate=sampleRate, .sampleSize=16, .channels=1, .data=data };
    Sound snd = LoadSoundFromWave(w); free(data); return snd;
}

void audio_load(AudioBank *a) {
    memset(a, 0, sizeof(*a));
    for (int i = 0; i < SFX_COUNT; i++) {
        char path[128];
        snprintf(path, sizeof(path), "assets/audio/%s.wav", SFX[i].name);
        if (FileExists(path)) {
            a->snd[i] = LoadSound(path);
            if (a->snd[i].frameCount) continue;
        }
        a->snd[i] = make_tone(SFX[i].freq, SFX[i].secs, SFX[i].decay, SFX[i].kind);
    }
    a->killThrottle = a->pickThrottle = 0;
}

void audio_unload(AudioBank *a) {
    for (int i = 0; i < SFX_COUNT; i++) UnloadSound(a->snd[i]);
    if (a->musicLoaded) { StopMusicStream(a->music); UnloadMusicStream(a->music); a->musicLoaded = false; }
}

void audio_play_pitched(AudioBank *a, SfxId id, float pitch, float volMul) {
    if (id < 0 || id >= SFX_COUNT || !a->snd[id].frameCount) return;
    SetSoundPitch(a->snd[id], pitch);
    SetSoundVolume(a->snd[id], SFX[id].vol * volMul * volume_curve(SETTINGS.sfxVol));
    PlaySound(a->snd[id]);
}

void audio_play(AudioBank *a, SfxId id) {
    if (id < 0 || id >= SFX_COUNT || !a->snd[id].frameCount) return;
    const SfxDef *d = &SFX[id];
    float pitch = d->pitchVar > 0 ? 1.0f + (arand()*2.0f - 1.0f) * d->pitchVar : 1.0f;
    audio_play_pitched(a, id, pitch, 1.0f);
}

void audio_update_throttles(AudioBank *a, float dt) {
    if (a->killThrottle > 0) a->killThrottle -= dt;
    if (a->pickThrottle > 0) a->pickThrottle -= dt;
}

void audio_play_kill(AudioBank *a) {
    if (a->killThrottle <= 0) { audio_play(a, SFX_EXPLODE); a->killThrottle = 0.03f; }
}
void audio_play_pickup(AudioBank *a) {
    if (a->pickThrottle <= 0) { audio_play(a, SFX_PICKUP); a->pickThrottle = 0.04f; }
}

// ---- music: one stream, faded out then swapped when the biome changes ----
#define MUSIC_FADE_RATE 1.6f   // full fade in ~0.6s

static void music_start(AudioBank *a, const char *slug) {
    char path[128];
    snprintf(path, sizeof(path), "assets/audio/music_%s.ogg", slug);
    if (!FileExists(path)) snprintf(path, sizeof(path), "assets/audio/music.ogg");
    if (FileExists(path)) {
        a->music = LoadMusicStream(path);
        a->musicLoaded = (a->music.frameCount > 0);
        if (a->musicLoaded) { a->music.looping = true; PlayMusicStream(a->music); }
    }
    snprintf(a->musicSlug, sizeof(a->musicSlug), "%s", slug);   // remember even when silent
}

void audio_music_update(AudioBank *a, float dt, const char *biomeSlug) {
    if (!IsAudioDeviceReady() || !biomeSlug) return;
    bool switching = strcmp(a->musicSlug, biomeSlug) != 0;
    if (switching && !a->musicLoaded) { music_start(a, biomeSlug); a->musicVol = 0; }
    if (!a->musicLoaded) return;
    if (switching) {
        a->musicVol -= MUSIC_FADE_RATE * dt;                    // fade the old track out...
        if (a->musicVol <= 0) {
            StopMusicStream(a->music); UnloadMusicStream(a->music); a->musicLoaded = false;
            music_start(a, biomeSlug); a->musicVol = 0;         // ...then swap and fade in
        }
    } else if (a->musicVol < 1.0f) {
        a->musicVol = fminf(1.0f, a->musicVol + MUSIC_FADE_RATE * dt);
    }
    if (a->musicLoaded) {
        SetMusicVolume(a->music, a->musicVol * volume_curve(SETTINGS.musicVol));
        UpdateMusicStream(a->music);
    }
}
